pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint256 v, bool includeTarget) public {
        vm.assume(from != address(0));

        Reverter reverter = new Reverter();

        address[] memory tos;
        if (includeTarget) {
            tos = new address[](1);
            tos[0] = address(reverter);
        } else {
            tos = new address[](0);
        }

        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        if (includeTarget) {
            assertTrue(ok == false);
        } else {
            assertTrue(ok == false);
        }
    }
}

contract Reverter {
    fallback() external payable { revert("revert"); }
}
